const meta={BUF:['Buffalo Bills','#00338d'],MIA:['Miami Dolphins','#008e97'],NE:['New England Patriots','#173453'],NYJ:['New York Jets','#125740'],BAL:['Baltimore Ravens','#38205c'],CIN:['Cincinnati Bengals','#e75a16'],CLE:['Cleveland Browns','#813f24'],PIT:['Pittsburgh Steelers','#726018'],HOU:['Houston Texans','#152d40'],IND:['Indianapolis Colts','#1b4a88'],JAX:['Jacksonville Jaguars','#007a80'],TEN:['Tennessee Titans','#4384af'],DEN:['Denver Broncos','#db5b1d'],KC:['Kansas City Chiefs','#d12c38'],LAC:['Los Angeles Chargers','#168cbd'],LV:['Las Vegas Raiders','#303539'],DAL:['Dallas Cowboys','#173757'],NYG:['New York Giants','#244e95'],PHI:['Philadelphia Eagles','#126064'],WSH:['Washington Commanders','#713b3d'],CHI:['Chicago Bears','#bf511d'],DET:['Detroit Lions','#1487bd'],GB:['Green Bay Packers','#315b44'],MIN:['Minnesota Vikings','#563188'],ATL:['Atlanta Falcons','#ab2936'],CAR:['Carolina Panthers','#167ca3'],NO:['New Orleans Saints','#9d8e68'],TB:['Tampa Bay Buccaneers','#bd2938'],ARI:['Arizona Cardinals','#9f3546'],LAR:['Los Angeles Rams','#3269b8'],SF:['San Francisco 49ers','#b23a38'],SEA:['Seattle Seahawks','#355c7d']};
