function loadPicks(){try{const q=new URLSearchParams(location.search),stored=JSON.parse(localStorage.getItem(KEY)||'{}');focus=q.get('team')||stored.focus||'CLE';if(!meta[focus])focus='CLE';picks=q.has('p')?JSON.parse(atob(q.get('p'))):{};}catch{picks={}}}
loadPicks();Object.keys(meta).sort((a,b)=>meta[a][0].localeCompare(meta[b][0])).forEach(t=>$('focus').add(new Option(meta[t][0],t)));$('focus').value=focus;
const afc=['BUF','MIA','NE','NYJ','BAL','CIN','CLE','PIT','HOU','IND','JAX','TEN','DEN','KC','LAC','LV'];
function storage(key,value){try{localStorage.setItem(key,JSON.stringify(value))}catch{toast('Device storage unavailable. Use a scenario link to save your picks.')}}
function toast(t){$('toast').textContent=t;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),3500)}
function percent(count,total=N){let p=100*count/total;if(!total)return '—';if(p>0&&p<.1)return '<0.1%';if(p<100&&p>99.9)return '>99.9%';return p.toFixed(1)+'%'}
function delta(v,b){let d=100*(v-b)/N;return {text:Math.abs(d)<.05?'—':(d>0?'+':'')+d.toFixed(1)+' pp',cls:d>.05?'up':d<-.05?'down':''}}
function record(t){let b={w:0,l:0,t:0};for(let g of data?.games||[]){if(g.h!==t&&g.a!==t)continue;let v=g.done?(g.hs===g.as_?.5:g.hs>g.as_?1:0):picks[g.id];if(v===undefined)continue;if(v===.5)b.t++;else if((v===1)===(g.h===t))b.w++;else b.l++}return b.w+'–'+b.l+(b.t?'–'+b.t:'')}

function setBusy(b){document.body.classList.toggle('is-computing',b);document.dispatchEvent(new Event('lab:state'));$('busyDot').classList.toggle('busy',b);$('standings').setAttribute('aria-busy',String(b));$('simStatus').textContent=b?'Updating your playoff picture…':'10,000 seasons simulated · save or share to keep your picks'}
function normalizePicks(obj){return Object.fromEntries(Object.entries(obj).filter(([id,v])=>[0,.5,1].includes(v)&&data.games.some(g=>g.id===id&&!g.done)))}
function applyPicks(next,remember=true){if(!data)return;if(remember){undoStack.push({...picks});if(undoStack.length>80)undoStack.shift();redoStack=[]}picks=normalizePicks(next);$('undo').disabled=!undoStack.length;$('redo').disabled=!redoStack.length;run()}
function run(){if(!data)return;version++;let v=version;worker?.terminate();storage(KEY,{picks,focus});setBusy(true);renderFocusHeader();renderOdds();renderGames();renderStrip();$('pickCount').textContent=Object.keys(picks).length?Object.keys(picks).length+' picks locked · '+(data.games.filter(g=>!g.done).length-Object.keys(picks).length)+' games simulated':'No picks yet · showing baseline';worker=new Worker('engine.js?v=4');baseline=baselineCache[focus];const send=(kind,p)=>worker.postMessage({data,picks:p,N,focus,version:v,kind});worker.onmessage=e=>{if(v!==version)return;if(e.data.error){setBusy(false);toast('Simulation error: '+e.data.error);$('simStatus').textContent='Simulation failed';return}if(e.data.kind==='baseline'){baseline=baselineCache[focus]=e.data;if(Object.keys(picks).length){send('scenario',picks);return}}output=e.data;setBusy(false);renderOdds();renderFocus();renderGames();renderRooting();renderSeeds();document.dispatchEvent(new Event('lab:update'))};worker.onerror=()=>{setBusy(false);$('simStatus').textContent='Simulation could not load. Please reload.'};if(!baseline)send('baseline',{});else if(!Object.keys(picks).length){output=baseline;setBusy(false);renderOdds();renderFocus();renderGames();renderRooting();renderSeeds();document.dispatchEvent(new Event('lab:update'))}else send('scenario',picks)}
function renderFocusHeader(){$('focusBadge').textContent=focus;$('focusBadge').style.setProperty('--team',meta[focus][1]);$('focus').value=focus;$('teamRecord').textContent=record(focus)+(Object.keys(picks).length?' with your picks · ':' record · ')+(afc.includes(focus)?'AFC':'NFC');$('seedTitle').textContent=short(focus)+' seed outlook'}
function renderFocus(){renderFocusHeader();if(!output||!baseline)return;let r=output.result[focus],b=baseline.result[focus];$('focusOdds').textContent=percent(r.play);$('focusDiv').textContent=percent(r.division);$('focusBye').textContent=percent(r.bye);$('focusWins').textContent=(r.wins/N).toFixed(1);[['focusDelta','play'],['divDelta','division'],['byeDelta','bye']].forEach(([id,k])=>{let d=delta(r[k],b[k]);$(id).textContent=d.text==='—'?'Same as baseline':d.text+' vs baseline';$(id).className=d.cls})}
function setFocus(t){focus=t;conf=afc.includes(t)?'AFC':'NFC';$('focus').value=t;syncConf();run()}
function syncConf(){document.querySelectorAll('[data-conf]').forEach(b=>b.classList.toggle('active',b.dataset.conf===conf))}
function renderOdds(){if(!output||!baseline)return;let metric=$('metric').value;let ts=Object.keys(meta).filter(t=>afc.includes(t)===(conf==='AFC'));ts.sort((a,b)=>output.result[b][metric]-output.result[a][metric]||output.result[b].wins-output.result[a].wins);$('metricHeading').textContent={play:'PLAYOFFS',division:'DIVISION',bye:'NO. 1 SEED'}[metric];$('standings').innerHTML=ts.map(t=>{let r=output.result[t],d=delta(r[metric],baseline.result[t][metric]);return `<tr class="${t===focus?'focused':''}"><td><button class="table-team" data-focus="${t}" aria-label="Follow ${meta[t][0]}"><span class="team-logo" style="--team:${meta[t][1]}">${t}</span><span><b>${short(t)}</b><small>${t===focus?'YOUR TEAM':meta[t][0].replace(' '+short(t),'')}</small></span></button></td><td class="td-record">${record(t)}</td><td><span class="odds-num">${percent(r[metric])}</span><span class="odds-meter"><i style="width:${100*r[metric]/N}%"></i></span></td><td class="delta ${d.cls}">${d.text}</td></tr>`}).join('');$('standings').querySelectorAll('[data-focus]').forEach(b=>b.onclick=()=>setFocus(b.dataset.focus))}
function renderSeeds(){let r=output.result[focus];$('seedChart').innerHTML=r.play?r.seeds.slice(1).map((v,i)=>`<div class="seed-bar" title="Seed ${i+1}: ${percent(v,r.play)} conditional on qualifying"><span>${percent(v,r.play)}</span><i style="height:${Math.max(1,65*v/r.play)}px"></i><b>${i+1}</b></div>`).join(''):'<p class="muted">No qualifying seasons in this simulation sample.</p>'}
function impact(g){let i=!document.body.classList.contains('is-computing')&&output?.focus===focus?output.impact[g.id]:null;if(!i||i.counts[0]<100||i.counts[2]<100||picks[g.id]!==undefined)return null;let a=100*i.qualified[0]/i.counts[0],h=100*i.qualified[2]/i.counts[2];let se=100*Math.sqrt((a/100)*(1-a/100)/i.counts[0]+(h/100)*(1-h/100)/i.counts[2]);return {a,h,swing:Math.abs(h-a),reliable:Math.abs(h-a)>1.96*se,help:h>=a?g.h:g.a,helpsHome:h>=a}}
function visibleGames(){let q=$('search').value.trim().toLowerCase(),filter=$('gameFilter').value;let gs=data.games.filter(g=>!g.done&&(week==='all'||g.week===+week));gs=gs.filter(g=>(filter!=='team'||g.h===focus||g.a===focus)&&(filter!=='unpicked'||picks[g.id]===undefined)&&(filter!=='picked'||picks[g.id]!==undefined)&&(!q||(meta[g.h][0]+' '+meta[g.a][0]+' '+g.h+' '+g.a).toLowerCase().includes(q)));if($('sort').value==='impact')gs.sort((a,b)=>(impact(b)?.swing??-1)-(impact(a)?.swing??-1));else gs.sort((a,b)=>new Date(a.date)-new Date(b.date));return gs}
function selectWeek(value){week=value==='all'?'all':+value;renderWeekNav();renderGames();renderRooting();}
function renderWeekNav(){let ws=[...new Set(data.games.filter(g=>!g.done).map(g=>g.week))].sort((a,b)=>a-b);if(!week||!ws.includes(+week)&&week!=='all')week=ws[0]||18;let options=[...ws,'all'];$('weekNav').innerHTML=ws.map(w=>`<button data-week="${w}" class="${+week===w?'active':''}" aria-pressed="${+week===w}" aria-label="Week ${w}"><span>WK</span><b>${w}</b></button>`).join('')+`<button data-week="all" class="${week==='all'?'active':''}" aria-pressed="${week==='all'}" aria-label="All remaining weeks"><span>REST</span><b>All</b></button>`;$('weekNav').querySelectorAll('button').forEach(b=>b.onclick=()=>selectWeek(b.dataset.week));$('weekSelect').innerHTML=options.map(w=>`<option value="${w}" ${String(w)===String(week)?'selected':''}>${w==='all'?'All remaining games':'Week '+w}</option>`).join('');let i=options.findIndex(w=>String(w)===String(week));$('previousWeek').disabled=i<=0;$('nextWeek').disabled=i>=options.length-1;$('weekSelect').onchange=e=>selectWeek(e.target.value);$('previousWeek').onclick=()=>selectWeek(options[i-1]);$('nextWeek').onclick=()=>selectWeek(options[i+1]);}
function matchupOutlook(g, estimate) {
 if (!estimate || document.body.classList.contains('is-computing')) return '';
 const outcome = (team, chance) => {
  const helps = estimate.reliable && estimate.help === team;
  return `<div class="outcome-cell${helps ? ' helps' : ''}"><span>If ${team} wins</span><strong>${chance.toFixed(1)}%</strong></div>`;
 };
 return `<section class="matchup-outlook" aria-label="${short(focus)} playoff outlook"><h4>${short(focus)} playoff odds</h4><div class="outcome-pair">${outcome(g.a, estimate.a)}${outcome(g.h, estimate.h)}</div></section>`;
}
function renderGames(){if(!data)return;let active=document.activeElement,focused=active?.dataset?.id?{id:active.dataset.id,value:active.dataset.v}:null;let gs=visibleGames();let allGames=gs;let gi=gs.findIndex(g=>g.id===guidedId);if(gi<0)gi=0;guidedId=gs[gi]?.id;document.getElementById('guidedControls').hidden=!guided||!gs.length;document.getElementById('guidedProgress').textContent=gs.length?'Game '+(gi+1)+' of '+gs.length:'';document.getElementById('guidedPrevious').disabled=gi===0;document.getElementById('guidedNext').disabled=gi>=gs.length-1;document.getElementById('guidedPrevious').onclick=()=>{guidedId=allGames[gi-1]?.id;renderGames()};document.getElementById('guidedNext').onclick=()=>{guidedId=allGames[gi+1]?.id;renderGames()};document.querySelectorAll('[data-game-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.gameFilter===$('gameFilter').value)));let chosen=gs.filter(g=>picks[g.id]!==undefined).length;$('weekProgress').style.width=(gs.length?100*chosen/gs.length:0)+'%';$('weekSummary').textContent=gs.length+(gs.length===1?' game · ':' games · ')+gs.filter(g=>picks[g.id]!==undefined).length+' picked';if(guided)gs=gs.slice(gi,gi+1);let lastDay='';$('gameList').innerHTML=gs.length?gs.map(g=>{let day=g.timeTBD?'Week '+g.week+' · Schedule TBD':new Date(g.date).toLocaleDateString('en-US',{weekday:'long',month:'short',day:'numeric'}),heading=day!==lastDay&&$('sort').value==='date'?`<div class="date-group">${day}${week==='all'?' · Week '+g.week:''}</div>`:'';lastDay=day;let locked=picks[g.id]!==undefined,im=impact(g);let time=g.timeTBD?'KICKOFF TBD':new Date(g.date).toLocaleTimeString('en-US',{hour:'numeric',minute:'2-digit',timeZoneName:'short'});function side(t,v,p){return `<button class="team-pick ${picks[g.id]===v?'selected':''}" data-id="${g.id}" data-v="${v}" aria-pressed="${picks[g.id]===v}" aria-label="Pick ${meta[t][0]} to win" style="--color:${meta[t][1]}"><span class="team-logo">${t}</span><span><span class="team-name">${short(t)}</span><span class="record">${record(t)}</span></span><span class="probability"><span class="pick-check" aria-hidden="true"><svg class="ui-icon" viewBox="0 0 24 24"><path d="m5 12 4 4L20 5"/></svg></span>${Math.round(p*100)}%</span></button>`}return `${heading}<article class="game ${locked?'picked':''}"><div class="game-top"><span>${g.a} ${g.neutral?'VS':'AT'} ${g.h} · ${time}</span><span class="${locked?'lock':''}">${locked?'YOUR PICK: '+(picks[g.id]===.5?'TIE':picks[g.id]===1?g.h:g.a):g.neutral?'NEUTRAL SITE':'MODEL WIN CHANCE'}</span></div><div class="matchup">${side(g.a,0,1-g.p)}<div class="versus"><span>${g.neutral?'VS':'@'}</span><button class="tie ${picks[g.id]===.5?'selected':''}" data-id="${g.id}" data-v="0.5" aria-pressed="${picks[g.id]===.5}" aria-label="Pick ${g.a} versus ${g.h} to tie">TIE</button></div>${side(g.h,1,g.p)}</div>${matchupOutlook(g,im)}<div class="impact-line">${im?.reliable?`<span>For ${short(focus)}: <b>${im.help} win helps</b></span><span>${im.swing.toFixed(1)} pp playoff swing</span>`:locked?'<span>Your pick is fixed in every simulation.</span><span>Tap again to clear</span>':im?'<span>Difference within simulation noise.</span>':'<span>Leave open to let the model decide.</span><span>Win chances exclude ties</span>'}</div></article>`}).join(''):'<div class="empty"><strong>No games in this view.</strong><br>Try another week or show all teams.<button id="clearGameFilters">Clear filters</button></div>';$('gameList').querySelectorAll('[data-id]').forEach(b=>b.onclick=()=>{let next={...picks},id=b.dataset.id,v=+b.dataset.v;if(next[id]===v)delete next[id];else next[id]=v;applyPicks(next)});if($('clearGameFilters'))$('clearGameFilters').onclick=()=>{$('search').value='';$('gameFilter').value='all';renderGames()};if(focused){let target=[...$('gameList').querySelectorAll('[data-id]')].find(b=>b.dataset.id===focused.id&&b.dataset.v===focused.value);target?.focus({preventScroll:true})}}
function renderStrip(){let locked=data.games.filter(g=>picks[g.id]!==undefined);$('scenarioStrip').innerHTML=locked.slice(-8).map(g=>`<button class="pick-chip" data-clear="${g.id}" aria-label="Clear pick for ${g.a} versus ${g.h}">W${g.week} · ${picks[g.id]===.5?g.a+'/'+g.h+' tie':picks[g.id]===1?g.h+' win':g.a+' win'}<span>×</span></button>`).join('')+(locked.length>8?`<span class="muted">+${locked.length-8} more picks</span>`:'');$('scenarioStrip').querySelectorAll('[data-clear]').forEach(b=>b.onclick=()=>{let next={...picks};delete next[b.dataset.clear];applyPicks(next)})}
function renderRooting(){if(!output)return;let gs=data.games.filter(g=>!g.done&&(week==='all'||g.week===+week)).map(g=>({g,i:impact(g)})).filter(x=>x.i&&x.i.reliable&&x.i.swing>=.5).sort((a,b)=>b.i.swing-a.i.swing).slice(0,4);$('rootingWeek').textContent=week==='all'?'REST OF SEASON':'WEEK '+week;$('rooting').innerHTML=gs.length?gs.map(({g,i})=>`<div class="rooting-row"><span class="team-logo" style="--team:${meta[i.help][1]}">${i.help}</span><span>Root for <strong>${short(i.help)}</strong><small class="rooting-match">${g.a} at ${g.h}</small></span><b>${i.swing.toFixed(1)} pp swing</b><button data-root="${g.id}" data-win="${i.help===g.h?1:0}">Pick win</button></div>`).join(''):'<p class="muted">No large unpicked swings in this view. Try “All” weeks or clear some picks.</p>';$('rooting').querySelectorAll('[data-root]').forEach(b=>b.onclick=()=>applyPicks({...picks,[b.dataset.root]:+b.dataset.win}))}
function saved(){try{return JSON.parse(localStorage.getItem(SAVED)||'[]')}catch{return []}}
function openSaved(){$('savedDialog').showModal();renderSaved()}
function renderSaved(){let list=saved();$('savedList').replaceChildren();if(!list.length){let empty=document.createElement('div');empty.className='saved-empty';empty.innerHTML='<h3>Your next scenario starts here.</h3><p>Make a few picks, name your scenario above, and save it for later.</p>';$('savedList').append(empty);}list.forEach((s,i)=>{let row=document.createElement('div');row.className='saved-row';let label=document.createElement('div');let strong=document.createElement('strong');strong.textContent=s.name;label.append(strong);let small=document.createElement('small');small.textContent=Object.keys(s.picks).length+' picks · '+new Date(s.date).toLocaleDateString();label.append(small);let controls=document.createElement('div');let load=document.createElement('button');load.textContent='Load';load.onclick=()=>{focus=meta[s.focus]?s.focus:'CLE';conf=afc.includes(focus)?'AFC':'NFC';syncConf();applyPicks(s.picks);$('savedDialog').close();toast('Scenario loaded')};let remove=document.createElement('button');remove.textContent='Delete';remove.onclick=()=>{let l=saved();l.splice(i,1);storage(SAVED,l);renderSaved()};controls.append(load,remove);row.append(label,controls);$('savedList').append(row)})}
function renderMethod(){let m=data.model,b=m.original,u=m.upgraded,improve=100*(b.brier-u.brier)/b.brier;let el=$('methodContent');el.innerHTML=`<h3>Game forecasts: measured, not assumed.</h3><p>The upgraded model adjusts point margins for opponent strength, shrinks sparse records toward the league average, carries a regressed prior-season rating, and includes home field and rest. Blowout margins are capped at 28 points. Ratings use a fixed 0.97 weekly decay and six-game ridge shrinkage. Coefficients were fitted on 2010–2021 regular seasons.</p><table class="evidence-table"><thead><tr><th>2023–2025 · ${u.games} GAMES</th><th>ORIGINAL</th><th>UPGRADED</th></tr></thead><tbody><tr><td>Brier error ↓</td><td>${b.brier.toFixed(4)}</td><td>${u.brier.toFixed(4)}</td></tr><tr><td>Log loss ↓</td><td>${b.logLoss.toFixed(4)}</td><td>${u.logLoss.toFixed(4)}</td></tr><tr><td>Winner accuracy ↑</td><td>${(b.accuracy*100).toFixed(1)}%</td><td>${(u.accuracy*100).toFixed(1)}%</td></tr></tbody></table><p>Brier error improved ${improve.toFixed(1)}% on this chronological test. A paired game-bootstrap interval for the difference spans zero (${m.brierDifference95CI.map(v=>v.toFixed(4)).join(' to ')}). That does not establish a statistically reliable advantage; game dependence can make the interval optimistic. No model parameters were tuned on these test results. Historical source revisions and parameters chosen during development limit claims about a pristine prospective test.</p><h3>What the playoff odds mean</h3><p>10,000 seeded seasons are simulated. Your picks are fixed; unpicked games use the fitted win probabilities and a fixed 0.4% tie assumption. Ratings are held fixed, and games are sampled independently. The model does not incorporate injuries, quarterback availability, betting prices or future team-strength uncertainty. These are scenario estimates, not betting advice.</p><p><strong>Playoff-event calibration has not been backtested.</strong> Better game-level error does not prove calibrated playoff odds. At 50%, Monte Carlo sampling error alone is about ±1 percentage point at 95%; model uncertainty is larger and not included. Displayed 0% / 100% are sample results, not mathematical elimination or clinching.</p><h3>Rooting guide</h3><p>Swings compare conditional playoff frequencies within this simulation. Guidance appears only when the estimated difference exceeds about two Monte Carlo standard errors. Small effects may be hidden; a displayed swing is still an estimate, and scanning many games can produce false positives.</p><h3>Tiebreakers & seeding</h3><p>The simulator selects four division champions and three wild cards in each conference, then orders seeds 1–7. It applies head-to-head (including multi-team wild-card sweeps), division and conference records, common games, strength of victory, strength of schedule, combined scoring/defense ranks and net points. Tied groups restart when they narrow. Future score margins are drawn from a logistic distribution conditional on the winner. This allows favorites to win by larger typical margins than underdogs. The score distribution is used for point-based tiebreakers and has not been historically validated. Net touchdowns are unavailable; unresolved ties use a seeded draw. This is substantially more complete than version 1, but is not an official clinching engine.</p><p>This scenario needed ${output?.fallbacks??'—'} unresolved tiebreaker draws across 10,000 seasons (a season can need several).</p><h3>Data freshness & reproducibility</h3><p>Snapshot: ${new Date(data.updated).toLocaleString()}. Completed games remain fixed. Scheduled kickoffs are converted from Eastern time. “Check for updates” reloads the latest published snapshot; it does not claim to fetch real-time scores. If automatic repository updates are not configured, rebuilding the data is required after games finish.</p><p>Current results and kickoffs: <a href="https://www.espn.com/nfl/scoreboard" target="_blank" rel="noopener">ESPN</a>. Historical scores and rest: <a href="https://github.com/nflverse/nfldata" target="_blank" rel="noopener">nflverse / nfldata</a>. <a href="https://www.nfl.com/standings/tie-breaking-procedures" target="_blank" rel="noopener">Official NFL tiebreaking rules</a>. <a href="validation.json" target="_blank">Download validation report</a>.</p><p class="muted">Model ${m.modelVersion} · Source fingerprint ${data.sourceSha256.slice(0,16)}…</p>`}
async function load(){try{let r=await fetch('data.json?v='+Date.now(),{cache:'no-store'});if(!r.ok)throw Error();let d=await r.json();if(d.games.length!==272||!d.model||d.games.some(g=>!meta[g.h]||!meta[g.a]))throw Error('Invalid snapshot');data=d;dataError=false;picks=normalizePicks(picks);baselineCache={};output=null;let remaining=d.games.filter(g=>!g.done).length;$('remaining').textContent=remaining;let age=(Date.now()-new Date(d.updated))/3600000;$('dataStatus').textContent=(age>36?'Snapshot may be stale · ':'Snapshot · ')+new Date(d.updated).toLocaleString('en-US',{month:'short',day:'numeric',hour:'numeric',minute:'2-digit',timeZoneName:'short'});conf=afc.includes(focus)?'AFC':'NFC';syncConf();renderWeekNav();renderFocusHeader();renderMethod();run();return true}catch(err){dataError=true;document.dispatchEvent(new Event('lab:dataerror'));$('dataStatus').textContent='Could not load season data';$('simStatus').textContent='Use “Check for updates” to retry';toast('Season snapshot could not load. Please try again.');return false}}
document.querySelectorAll('[data-game-filter]').forEach(b=>b.onclick=()=>{$('gameFilter').value=b.dataset.gameFilter;renderGames()});
$('focus').onchange=()=>setFocus($('focus').value);$('search').oninput=renderGames;$('gameFilter').onchange=renderGames;$('sort').onchange=renderGames;$('metric').onchange=renderOdds;
$('undo').onclick=()=>{if(!undoStack.length)return;redoStack.push({...picks});applyPicks(undoStack.pop(),false)};$('redo').onclick=()=>{if(!redoStack.length)return;undoStack.push({...picks});applyPicks(redoStack.pop(),false)};
function clearAllPicks(){let u=new URL(location.href);u.searchParams.delete('p');history.replaceState(history.state,'',u.href);applyPicks({});toast('All picks cleared. Undo is available.')} $('reset').onclick=clearAllPicks;$('clearAllPicks').onclick=clearAllPicks;function teamBatch(value){let next={...picks};data.games.filter(g=>!g.done&&(g.h===focus||g.a===focus)).forEach(g=>{if(value==='clear')delete next[g.id];else next[g.id]=(g.h===focus)===(value==='win')?1:0});applyPicks(next)};$('winout').onclick=()=>teamBatch('win');$('loseout').onclick=()=>teamBatch('lose');$('clearTeam').onclick=()=>teamBatch('clear');$('favorites').onclick=()=>{let next={...picks};visibleGames().forEach(g=>next[g.id]=g.p>=.5?1:0);applyPicks(next)};
document.querySelectorAll('[data-conf]').forEach(b=>b.onclick=()=>{conf=b.dataset.conf;syncConf();renderOdds()});document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{document.body.classList.toggle('odds-view',b.dataset.view==='odds');document.querySelectorAll('[data-view]').forEach(x=>x.classList.toggle('active',x===b))});
$('share').onclick=async()=>{let u=new URL(location.href);u.search='';u.searchParams.set('tab','simulator');u.searchParams.set('p',btoa(JSON.stringify(picks)));u.searchParams.set('team',focus);try{await navigator.clipboard.writeText(u.href);toast('Scenario link copied')}catch{toast('Copy the link from the address bar');history.replaceState(null,'',u.href)}};
$('savedBtn').onclick=openSaved;$('saveBtn').onclick=openSaved;$('saveConfirm').onclick=()=>{let name=$('scenarioName').value.trim()||short(focus)+' scenario';let list=saved();list.unshift({name,picks:{...picks},focus,date:new Date().toISOString()});storage(SAVED,list.slice(0,30));$('scenarioName').value='';renderSaved();toast('Scenario saved on this device')};
for(let id of ['methodBtn','accuracyBtn'])$(id).onclick=()=>{if(data)renderMethod();$('methodDialog').showModal()};document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>$(b.dataset.close).close());document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){let r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}}));$('exploreNav').onclick=()=>window.scrollTo({top:0,behavior:'smooth'});$('refresh').onclick=async()=>{let prev=data?.updated;let ok=await load();if(!ok)return;toast(data?.updated===prev?'You have the latest published snapshot':'Published snapshot updated')};load();

function setPickingMode(value){guided=value;document.body.classList.toggle('guided-picking',value);$('guidedMode').classList.toggle('active',value);$('listMode').classList.toggle('active',!value);$('guidedMode').setAttribute('aria-pressed',String(value));$('listMode').setAttribute('aria-pressed',String(!value));renderGames()}
$('guidedMode').onclick=()=>setPickingMode(true);$('listMode').onclick=()=>setPickingMode(false);$('jumpToGames').onclick=()=>document.querySelector('.games-section').scrollIntoView({block:'start',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});

function autoPickGames(scope, selectedWeek){
 if(!data)return;
 const next={...picks};let added=0;
 for(const g of data.games){
  if(!g.done&&next[g.id]===undefined&&(scope==='season'||+g.week===+selectedWeek)){
   next[g.id]=g.p>=.5?1:0;added++;
  }
 }
 if(!added){toast('No unpicked games left in '+(scope==='season'?'the season':'Week '+selectedWeek)+'. Clear picks to start over.');return}
 applyPicks(next);
 toast(added+' games auto-picked'+(scope==='season'?' for the rest of the season':' in Week '+selectedWeek)+'. Existing picks kept. Undo is available.');
}
function renderAutoPick(){
 if(!data)return;
 const select=$('autoPickWeek'),old=select.value;
 const weeks=[...new Set(data.games.filter(g=>!g.done).map(g=>+g.week))].sort((a,b)=>a-b);
 select.innerHTML=weeks.map(w=>`<option value="${w}">Week ${w}</option>`).join('');
 select.value=weeks.includes(+old)?old:String(weeks.includes(+week)?week:weeks[0]||'');
 const remaining=data.games.filter(g=>!g.done&&picks[g.id]===undefined);
 const count=remaining.filter(g=>+g.week===+select.value).length;
 $('autoPickWeekButton').textContent=select.value?'Auto-pick Week '+select.value+' ('+count+')':'No remaining weeks';
 $('autoPickWeekButton').disabled=!count;select.disabled=!weeks.length;
 document.querySelectorAll('[data-pick-season]').forEach(b=>{b.textContent='Auto-pick rest of season ('+remaining.length+')';b.disabled=!remaining.length});
 $('autoPickSummary').textContent=remaining.length+' unpicked games this season · '+count+' in '+(select.value?'Week '+select.value:'the selected week');
}
$('autoPickWeek').onchange=renderAutoPick;
$('autoPickWeekButton').onclick=()=>autoPickGames('week',$('autoPickWeek').value);
document.querySelectorAll('[data-pick-season]').forEach(b=>b.onclick=()=>autoPickGames('season'));
$('favorites').textContent='Auto-pick games…';
$('favorites').onclick=()=>{if(week!=='all')$('autoPickWeek').value=String(week);renderAutoPick();document.querySelector('.season-autopick').scrollIntoView({block:'center',behavior:'smooth'});$('autoPickWeekButton').focus({preventScroll:true})};
document.addEventListener('lab:state',renderAutoPick);
document.addEventListener('lab:update',renderAutoPick);
